//! The FissionOxide brand for Rust apps: colour families, neutrals, light and dark themes, the
//! desktop app's palette, font names and the fox logo.
//!
//! [`tokens`] and [`logo`] are generated by `brand/build.py` from `brand/tokens.json` and
//! `brand/logo/fox.json`, the same sources as the logo files and the website's CSS; edit those
//! and re-run the script rather than editing the generated code. The crate has no dependencies,
//! so any UI toolkit can turn an [`Rgb`] into its own colour type.

pub mod logo;
pub mod tokens;

pub use tokens::*;

/// An sRGB colour.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Rgb(pub u8, pub u8, pub u8);

impl Rgb {
  /// `#rrggbb`.
  pub fn hex(self) -> String {
    format!("#{:02X}{:02X}{:02X}", self.0, self.1, self.2)
  }
}

/// A colour family: `base` is the colour of the family's icons and accents, `light`, `dark` and
/// `deep` the fox's lit and shaded facets and hover / pressed states.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Family {
  pub light: Rgb,
  pub base: Rgb,
  pub dark: Rgb,
  pub deep: Rgb,
}

impl Family {
  /// The shades lightest first.
  pub const fn shades(self) -> [Rgb; 4] {
    [self.light, self.base, self.dark, self.deep]
  }
}

#[cfg(test)]
mod tests {
  use super::*;

  #[test]
  fn the_fox_wears_the_logo_families() {
    let shades: Vec<Rgb> = FAMILIES[..6].iter().flat_map(|(_, f)| f.shades()).collect();
    for f in logo::FACETS {
      assert!(shades.contains(&f.color), "{} is not a logo family shade", f.color.hex());
      assert!(f.points.len() >= 3);
      for &(x, y) in f.points {
        assert!((0.0..=logo::SIZE.0).contains(&x) && (0.0..=logo::SIZE.1).contains(&y));
      }
    }
  }

  #[test]
  fn hex_round_trip() {
    assert_eq!(BLUE.base.hex(), "#1E88E5");
    assert_eq!(app::ACCENT, BLUE.base);
  }
}
